async function e(e,t){let n=await fetch(`${e}`,{headers:{"Content-Type":`application/json`},...t}),r=await n.json().catch(()=>null);if(!n.ok)throw Error(r&&r.error||n.statusText||`Error en la API`);return r}async function t(t){return e(`/api/employees`,{method:`POST`,body:JSON.stringify(t)})}async function n(t){return e(`/api/employees?walletAddress=${encodeURIComponent(t)}`)}async function r(t){return e(`/api/wallets?address=${encodeURIComponent(t)}`)}async function i(t,n){return e(`/api/wallets/register`,{method:`POST`,body:JSON.stringify({address:t,role:n})})}async function a(){return e(`/api/jobs`)}async function o(t){return e(`/api/jobs`,{method:`POST`,body:JSON.stringify(t)})}async function s(t){return e(`/api/applications/apply`,{method:`POST`,body:JSON.stringify(t)})}export{r as a,a as i,o as n,t as o,n as r,i as s,s as t};